API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Edge_Router, "Edge Router", "Custom edge router with integrated TLS termination", "Handles routing, TLS termination, and forwards incoming user requests.")
    Component(Security_Manager, "Security Manager", "OAuth2/OIDC validation module", "Validates IAM tokens and handles security checks.")
    Component(Caching_Manager, "Caching Manager", "Redis Client", "Manages caching of frequent search queries and serves fallback responses.")
    Component(Resiliency_and_Rate_Limiting_Controller, "Resiliency and Rate Limiting Controller", "Circuit Breaker and Rate Limiting patterns", "Enforces rate limits and provides circuit breaker patterns for backend protection.")
}

Rel(Edge_Router, Security_Manager, "Delegates token validation")
Rel(Edge_Router, Resiliency_and_Rate_Limiting_Controller, "Applies rate limiting and circuit breaking")
Rel(Edge_Router, Caching_Manager, "Checks and stores cached query responses")

@enduml

Search Engine Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(search_engine_container, "Search Engine Container") {
    Component(search_api_endpoint, "Search API Endpoint", "HTTP/REST Handler", "Receives search queries from Core Business Services.")
    Component(index_ingestion_consumer, "Index Ingestion Consumer", "Event Listener", "Consumes asynchronous update events from the Async Event Broker Container to update the search index.")
    Component(search_index_engine, "Search Index Engine", "Elasticsearch / OpenSearch", "Delivers high-performance item discovery and sub-800ms 99th-percentile search capabilities.")
}

Rel(index_ingestion_consumer, search_index_engine, "Ingests asynchronous updates", "HTTP/REST")

@enduml

Async Event Broker Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(async_event_broker_container, "Async Event Broker Container") {
    Component(Event_Publisher, "Event Publisher", "Apache Kafka / RabbitMQ Client", "Publishes asynchronous events with Avro/JSON Schema governance and IAM-backed ACLs.")
    Component(Event_Consumer, "Event Consumer", "Apache Kafka / RabbitMQ Client", "Consumes asynchronous events and handles consumer idempotency deduplication.")
}

Rel(Event_Publisher, Event_Consumer, "Transmits asynchronous messages via AMQP/Kafka protocol", "AMQP/Kafka")
@enduml

Shared Caching Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Shared Caching Container container

Container_Boundary(shared_caching_container, "Shared Caching Container") {
    Component(Cache_Manager, "Cache Manager", "Redis In-Memory Engine", "Manages in-memory data access and eviction policies to support sub-800ms search performance.")
    Component(Session_Store, "Session Store", "Redis KV Store", "Stores active patron and staff session states for the self-service portals.")
}

Rel(Cache_Manager, Session_Store, "Persists and retrieves cached data entries", "Redis protocol")

@enduml

File Storage Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("File Storage Container", "File Storage Container") {
    Component(Storage_Handler, "Storage Handler", "S3/HTTPS Compatible Storage API", "Manages secure asset persistence and enforces EU-only data residency policies for uploaded files.")
    Component(Pre_signed_URL_Generator, "Pre-signed URL Generator", "HTTPS Service", "Generates secure pre-signed URLs allowing clients to upload and retrieve files directly.")
}

Rel(Storage_Handler, Pre_signed_URL_Generator, "Provides secure file storage access")

@enduml
